import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        long[] a = {nextLong(), nextLong(), nextLong()};
        long best = -1;
        int[][] pairs = {{0, 1}, {0, 2}, {1, 2}};
        // Clearing flavors i and j is possible iff their counts agree mod 3, and then takes max of the two.
        for (int[] p : pairs)
            if (a[p[0]] % 3 == a[p[1]] % 3) {
                long steps = Math.max(a[p[0]], a[p[1]]);
                if (best < 0 || steps < best) best = steps;
            }
        System.out.println(best);
    }
}

